import hashlib
import hmac
import time
import re
import os
from urllib.parse import urlparse, parse_qs, urlencode, quote


class RequestSigner:
    """Signs HTTP requests using HMAC-SHA256 with canonicalized components.

    Security features:
    - Constant-time signature comparison
    - Timestamp-based replay protection
    - Canonical request format to prevent ambiguity
    - Header allowlist to prevent header injection
    """

    ALLOWED_SIGN_HEADERS = frozenset([
        'content-type', 'host', 'x-request-id', 'x-forwarded-for',
        'accept', 'content-length', 'authorization'
    ])

    MAX_CLOCK_SKEW = 300  # 5 minutes

    def __init__(self, secret_key: bytes, service_id: str):
        if len(secret_key) < 32:
            raise ValueError("Secret key must be at least 32 bytes")
        if not re.match(r'^[a-zA-Z0-9_-]+$', service_id):
            raise ValueError("Invalid service_id")
        self._secret = secret_key
        self._service_id = service_id

    def _canonicalize_path(self, path: str) -> str:
        """Normalize path component for signing."""
        # Remove double slashes, resolve . and ..
        segments = []
        for seg in path.split('/'):
            if seg == '..' and segments:
                segments.pop()
            elif seg and seg != '.':
                segments.append(quote(seg, safe=''))
        return '/' + '/'.join(segments)

    def _canonicalize_query(self, query_string: str) -> str:
        """Sort query parameters for consistent signing."""
        if not query_string:
            return ''
        params = parse_qs(query_string, keep_blank_values=True)
        sorted_params = []
        for key in sorted(params.keys()):
            for value in sorted(params[key]):
                sorted_params.append((quote(key, safe=''), quote(value, safe='')))
        return urlencode(sorted_params, quote_via=lambda s, *a, **k: s)

    def _canonicalize_headers(self, headers: dict) -> str:
        """Canonicalize headers for signing - lowercase keys, trim values."""
        canonical = []
        for key in sorted(headers.keys(), key=str.lower):
            lower_key = key.lower()
            if lower_key in self.ALLOWED_SIGN_HEADERS:
                value = ' '.join(headers[key].split())  # normalize whitespace
                canonical.append(f"{lower_key}:{value}")
        return '\n'.join(canonical)

    def _build_signing_string(self, method: str, url: str, headers: dict,
                               timestamp: int) -> str:
        """Build the canonical string to sign."""
        parsed = urlparse(url)
        canonical_path = self._canonicalize_path(parsed.path)
        canonical_query = self._canonicalize_query(parsed.query)
        canonical_headers = self._canonicalize_headers(headers)

        # Count signed headers
        signed_header_names = ';'.join(
            sorted(k.lower() for k in headers.keys() 
                   if k.lower() in self.ALLOWED_SIGN_HEADERS)
        )

        signing_string = '\n'.join([
            method.upper(),
            canonical_path,
            canonical_query,
            canonical_headers,
            signed_header_names,
            str(timestamp),
            self._service_id
        ])
        return signing_string

    def sign_request(self, method: str, url: str, headers: dict) -> dict:
        """Sign a request and return auth headers to add."""
        timestamp = int(time.time())
        signing_string = self._build_signing_string(
            method, url, headers, timestamp
        )

        signature = hmac.new(
            self._secret,
            signing_string.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()

        signed_headers = ';'.join(
            sorted(k.lower() for k in headers.keys()
                   if k.lower() in self.ALLOWED_SIGN_HEADERS)
        )

        return {
            'X-Auth-Timestamp': str(timestamp),
            'X-Auth-Signature': signature,
            'X-Auth-SignedHeaders': signed_headers,
            'X-Auth-Service': self._service_id
        }

    def verify_request(self, method: str, url: str, headers: dict) -> bool:
        """Verify a signed request."""
        try:
            timestamp = int(headers.get('X-Auth-Timestamp', '0'))
            provided_sig = headers.get('X-Auth-Signature', '')
            service = headers.get('X-Auth-Service', '')

            # Replay protection
            current_time = int(time.time())
            if abs(current_time - timestamp) > self.MAX_CLOCK_SKEW:
                return False

            # Service validation
            if service != self._service_id:
                return False

            # Rebuild and verify signature
            signing_string = self._build_signing_string(
                method, url, headers, timestamp
            )

            expected_sig = hmac.new(
                self._secret,
                signing_string.encode('utf-8'),
                hashlib.sha256
            ).hexdigest()

            return hmac.compare_digest(expected_sig, provided_sig)

        except (ValueError, TypeError, AttributeError):
            return False


class RequestVerifierMiddleware:
    """WSGI middleware that verifies request signatures."""

    def __init__(self, app, secret_key: bytes, service_id: str,
                 exempt_paths=None):
        self._app = app
        self._signer = RequestSigner(secret_key, service_id)
        self._exempt = set(exempt_paths or [])

    def _extract_headers(self, environ: dict) -> dict:
        """Extract HTTP headers from WSGI environ."""
        headers = {}
        for key, value in environ.items():
            if key.startswith('HTTP_'):
                # Convert HTTP_CONTENT_TYPE -> Content-Type
                header_name = key[5:].replace('_', '-').title()
                headers[header_name] = value
            elif key == 'CONTENT_TYPE':
                headers['Content-Type'] = value
            elif key == 'CONTENT_LENGTH':
                headers['Content-Length'] = value
        return headers

    def _build_url(self, environ: dict) -> str:
        """Reconstruct request URL from WSGI environ."""
        scheme = environ.get('wsgi.url_scheme', 'http')
        host = environ.get('HTTP_HOST', environ.get('SERVER_NAME', 'localhost'))
        path = environ.get('PATH_INFO', '/')
        query = environ.get('QUERY_STRING', '')
        url = f"{scheme}://{host}{path}"
        if query:
            url += f"?{query}"
        return url

    def __call__(self, environ, start_response):
        path = environ.get('PATH_INFO', '/')

        # Check exemptions
        if path in self._exempt:
            return self._app(environ, start_response)

        headers = self._extract_headers(environ)
        method = environ.get('REQUEST_METHOD', 'GET')
        url = self._build_url(environ)

        if not self._signer.verify_request(method, url, headers):
            start_response('401 Unauthorized', [
                ('Content-Type', 'text/plain'),
                ('WWW-Authenticate', 'HMAC-SHA256')
            ])
            return [b'Request signature verification failed']

        return self._app(environ, start_response)
